def second_largest_distinct(values):
    first = None
    second = None

    for x in values:
        if first is None or x > first:
            if x != first:
                second = first
                first = x
        elif x != first and (second is None or x > second):
            second = x

    if second is None:
        raise ValueError("Fewer than two distinct numbers")
    return second
```
