def balanced_parentheses(text):
    balance = 0
    for ch in text:
        if ch == "(":
            balance += 1
        else:  # input contains only '(' and ')'
            balance -= 1
        if balance < 0:
            return False
    return balance == 0
```
The balance must never become negative, and it must return to zero at the end.

def is_balanced(s):
    depth = 0
    for char in s:
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

The counter tracks unmatched opening parentheses. The string is unbalanced if a closing parenthesis appears without a match or if any opening parentheses remain at the end.

def balanced(s):
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

